package com.rustybank.legacy;

import java.math.BigDecimal;
import java.math.RoundingMode;

/**
 * MONEY HELPERS
 * Rewritten to use exact integer cent arithmetic.
 */
public class MoneyUtil {

    public static long parse(String amount) {
        if (amount == null) {
            throw new IllegalArgumentException("INVALID AMOUNT");
        }
        String trimmed = amount.trim();
        if (trimmed.isEmpty()) {
            throw new IllegalArgumentException("INVALID AMOUNT");
        }

        // Use BigDecimal for exact parsing of decimal strings of any size
        BigDecimal bd;
        try {
            bd = new BigDecimal(trimmed);
        } catch (NumberFormatException e) {
            throw new IllegalArgumentException("INVALID AMOUNT: " + amount);
        }

        if (bd.signum() <= 0) {
            throw new IllegalArgumentException("INVALID AMOUNT: " + amount);
        }

        // Convert to cents (multiply by 100) with exact scale
        BigDecimal centsBD = bd.multiply(BigDecimal.valueOf(100));
        // Input should have at most 2 decimal places; if more, round half-up to nearest cent
        if (centsBD.scale() > 0) {
            centsBD = centsBD.setScale(0, RoundingMode.HALF_UP);
        }

        try {
            return centsBD.longValueExact();
        } catch (ArithmeticException e) {
            throw new IllegalArgumentException("AMOUNT TOO LARGE: " + amount);
        }
    }

    /** Prints an amount for the teller screen, 2 decimals. */
    public static String format(long cents) {
        long whole = cents / 100;
        long frac = cents % 100;
        if (frac < 0) {
            frac = -frac; // should never happen with validated amounts
        }
        return whole + "." + (frac < 10 ? "0" : "") + frac;
    }
}

