package com.rustybank.legacy;

import java.math.BigDecimal;
import java.math.RoundingMode;

/**
 * INTEREST RUN
 * CHG 17.01.2001 - rounding added after complaint from branch 0042
 * CHG TODAY - exact arithmetic using BigDecimal for rate, integer cents for balance
 */
public class InterestCalculator {

    /**
     * Computes monthly interest: balance * annualRatePercent / 100 / 12,
     * rounded half-up to the cent.
     *
     * @param balanceCents     account balance in cents (>= 0)
     * @param annualRatePercent annual rate as a string, e.g. "3" or "4.5"
     * @return interest in cents, rounded half-up
     */
    public long monthlyInterest(long balanceCents, String annualRatePercent) {
        BigDecimal rate = new BigDecimal(annualRatePercent.trim());
        // interest_cents = balance_cents * rate / 1200, rounded half-up
        BigDecimal interest = BigDecimal.valueOf(balanceCents)
                .multiply(rate)
                .divide(BigDecimal.valueOf(1200), RoundingMode.HALF_UP);
        return interest.longValueExact();
    }
}

