package com.rustybank.legacy;

import java.util.ArrayList;
import java.util.List;

/**
 * SPLIT PAYMENTS (standing orders to several payees)
 * CHG TODAY - exact integer cent arithmetic with fair remainder distribution
 */
public class PaymentSplitter {

    /**
     * Splits totalCents into payees equal whole-cent shares.
     * Remainder cents go one each to the first payees in the list.
     *
     * @param totalCents total amount in cents (> 0)
     * @param payees     number of payees (> 0)
     * @return list of shares in cents, one per payee, summing to totalCents
     */
    public List<Long> split(long totalCents, int payees) {
        long baseShare = totalCents / payees;
        long remainder = totalCents % payees;

        List<Long> shares = new ArrayList<>(payees);
        for (int i = 0; i < payees; i++) {
            shares.add(baseShare + (i < remainder ? 1 : 0));
        }
        return shares;
    }
}

