package com.rustybank.legacy;

import com.rustybank.TellerTerminal;

import java.util.ArrayList;
import java.util.List;

/**
 * TELLER TERMINAL PROGRAM
 * CREATED 12.03.1999
 * CHG 09.09.2009 - migrated from the green screens, logic unchanged
 * CHG TODAY - rewritten for exact cent arithmetic
 */
public class LegacyTellerTerminal implements TellerTerminal {

    private AccountStore store;
    private InterestCalculator interestCalculator = new InterestCalculator();
    private PaymentSplitter paymentSplitter = new PaymentSplitter();

    public LegacyTellerTerminal(AccountStore store) {
        this.store = store;
    }

    public void openAccount(String accountId) {
        store.add(accountId);
    }

    public void deposit(String accountId, String amount) {
        Account a = store.find(accountId);
        long cents = MoneyUtil.parse(amount);
        a.setBalanceCents(a.getBalanceCents() + cents);
    }

    public void withdraw(String accountId, String amount) {
        Account a = store.find(accountId);
        long cents = MoneyUtil.parse(amount);
        if (cents > a.getBalanceCents()) {
            throw new IllegalStateException("INSUFFICIENT FUNDS");
        }
        a.setBalanceCents(a.getBalanceCents() - cents);
    }

    public String balance(String accountId) {
        return MoneyUtil.format(store.find(accountId).getBalanceCents());
    }

    public String postMonthlyInterest(String accountId, String annualRatePercent) {
        Account a = store.find(accountId);
        long interestCents = interestCalculator.monthlyInterest(a.getBalanceCents(), annualRatePercent);
        a.setBalanceCents(a.getBalanceCents() + interestCents);
        return MoneyUtil.format(interestCents);
    }

    public List<String> splitPayment(String fromAccountId, String amount, List<String> payeeIds) {
        Account from = store.find(fromAccountId);
        if (payeeIds == null || payeeIds.isEmpty()) {
            throw new IllegalArgumentException("NO PAYEES");
        }
        List<Account> payees = new ArrayList<>(payeeIds.size());
        for (String payeeId : payeeIds) {
            payees.add(store.find(payeeId));
        }
        long totalCents = MoneyUtil.parse(amount);
        if (totalCents > from.getBalanceCents()) {
            throw new IllegalStateException("INSUFFICIENT FUNDS");
        }
        List<Long> shareCentsList = paymentSplitter.split(totalCents, payees.size());
        from.setBalanceCents(from.getBalanceCents() - totalCents);
        List<String> shares = new ArrayList<>(payees.size());
        for (int i = 0; i < payees.size(); i++) {
            Account p = payees.get(i);
            long share = shareCentsList.get(i);
            p.setBalanceCents(p.getBalanceCents() + share);
            shares.add(MoneyUtil.format(share));
        }
        return shares;
    }

    public String totalHoldings() {
        long sumCents = 0;
        List<Account> all = store.all();
        for (Account a : all) {
            sumCents += a.getBalanceCents();
        }
        return MoneyUtil.format(sumCents);
    }
}
